    const consoleMsgs = [];
    page.on('console', msg => consoleMsgs.push(msg.type() + ': ' + msg.text()));
    page.on('pageerror', err => consoleMsgs.push('pageerror: ' + err.message));
    await page.goto('http://127.0.0.1:4173/ung-vien-tuyen-dung.html', { waitUntil: 'networkidle' });
