    await page.goto(url, { waitUntil: 'load' });
    await page.waitForTimeout(1600);
    await page.click('.jobs-recruiter-manage-btn');
    await page.waitForTimeout(300);

    const data = await page.evaluate(() => {
      const panel = document.getElementById('recruiterFocusPanel');
      const controls = panel ? panel.querySelector('.jobs-recruiter-focus-controls') : null;
      const actions = panel ? panel.querySelector('.jobs-recruiter-focus-actions') : null;
      const opsGrid = panel ? panel.querySelector('.jobs-recruiter-ops-grid') : null;
      const buttons = actions ? Array.from(actions.querySelectorAll('button,a')) : [];
      const r = panel ? panel.getBoundingClientRect() : null;
      const vw = window.innerWidth;
      const over = [];
      if (panel && r) {
        panel.querySelectorAll('*').forEach((el) => {
          const er = el.getBoundingClientRect();
          if (er.right > r.right + 1) {
            if (over.length < 8) {
              over.push({
                tag: el.tagName,
                cls: el.className,
                text: (el.textContent || '').trim().slice(0, 32),
                diff: Number((er.right - r.right).toFixed(2))
              });
            }
          }
        });
      }
      return {
        viewport: { width: vw, height: window.innerHeight },
        panelRect: r ? {
          x: Number(r.x.toFixed(2)),
          y: Number(r.y.toFixed(2)),
          width: Number(r.width.toFixed(2)),
          height: Number(r.height.toFixed(2)),
          right: Number(r.right.toFixed(2))
        } : null,
        centeredDelta: r ? Number((vw / 2 - (r.left + r.width / 2)).toFixed(2)) : null,
        panelCss: panel ? {
          position: getComputedStyle(panel).position,
          left: getComputedStyle(panel).left,
          right: getComputedStyle(panel).right,
          top: getComputedStyle(panel).top,
          width: getComputedStyle(panel).width,
          transform: getComputedStyle(panel).transform
        } : null,
        controlsCols: controls ? getComputedStyle(controls).gridTemplateColumns : null,
        actionsJustify: actions ? getComputedStyle(actions).justifyContent : null,
        opsCols: opsGrid ? getComputedStyle(opsGrid).gridTemplateColumns : null,
        btnWidths: buttons.map((b) => Number(b.getBoundingClientRect().width.toFixed(2))),
        panelScroll: panel ? {
