          scrollH: panel.scrollHeight
        } : null,
        overflowX: document.documentElement.scrollWidth - document.documentElement.clientWidth,
        bodyLocked: document.body.classList.contains('is-recruiter-focus-open'),
        overInside: over
      };
    });

